/** Helpers for mixer CSV fields: school, role, and URL-only links. */

export function normalizeUrl(raw) {
  if (!raw) return '';
  let url = String(raw).trim().replace(/[.,)]+$/, '');
  if (!url) return '';
  if (!/^https?:\/\//i.test(url)) {
    url = `https://${url.replace(/^\/+/, '')}`;
  }
  return url;
}

/** Extra URLs from import (pipe-separated), excluding LinkedIn already shown separately. */
export function parseExtraLinks(linksField, linkedInUrl) {
  if (!linksField) return [];
  const linked = normalizeUrl(linkedInUrl);
  const seen = new Set(linked ? [linked.toLowerCase()] : []);
  const out = [];
  for (const part of String(linksField).split('|')) {
    const url = normalizeUrl(part);
    if (!url) continue;
    const key = url.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(url);
  }
  return out;
}

export function linkLabel(url) {
  try {
    const host = new URL(url).hostname.replace(/^www\./, '');
    return host || url;
  } catch {
    return url.length > 40 ? `${url.slice(0, 40)}…` : url;
  }
}

/** Map Cypher record aliases (source/target) to graph node profile fields. */
export function profileFromRecord(record, side) {
  const school =
    record.get(`${side}School`) || record.get(`${side}Location`) || '';
  return {
    role: record.get(`${side}Role`) || '',
    school,
    website: record.get(`${side}Website`) || '',
    email: record.get(`${side}Email`) || '',
    links: record.get(`${side}Links`) || '',
  };
}

export function profileFromNeo4jProps(props = {}) {
  return {
    role: props.role || '',
    school: props.school || props.location || '',
    website: props.website || '',
    email: props.email || '',
    links: props.links || '',
  };
}
